Rules.InvariantScript:
If(
    !startTimer && Timer1.Value = 0,

    // ✅ FIRST CLICK → start timer + assign user
    Reset(Timer1);

    // ✅ Set assignment to Accepted on first click
    Patch(
        AssignedUsers,
        LookUp(
            AssignedUsers,
            UserId = currentUserID &&
            EmergencyId = selectedEmergency.ID
        ),
        {
            AUStatus: { Value: "Accepted" }
        }
    );

    UpdateContext({ startTimer: true }),


    // ✅ SECOND CLICK → stop + save result
    startTimer,

    With(
        { hoursSpent: Round(Timer1.Value / 3600000, 2) },

        // ✅ Update user hours
        Patch(
            Users,
            LookUp(Users, ID = currentUserID),
            {
                HoursWorked:
                    LookUp(Users, ID = currentUserID).HoursWorked + hoursSpent
            }
        );

        UpdateContext(
            {
                startTimer: false,
                finalHours: hoursSpent
            }
        )
    )
)

Patch(
            AssignedUsers,
            LookUp(
                AssignedUsers,
                UserId = currentUserID &&
                EmergencyId = selectedEmergency.ID   // ✅ NUMBER = NUMBER
            ),
            {
                AUStatus: { Value: "Declined" }   // ✅ choice field
            }
        );
Notify("Assignment declined, returning to dashboard");
Navigate(VolunteerDashboard)

Patch(
    Emergencies,
    selectedEmergency,
    {
        Status: { Value: "Completed" }
    }
);

Notify(
    "Emergency marked as completed",
    NotificationType.Success
);

Set(currentUserID, Blank());

Navigate(LoginScreen);

Notify(
    "You have been logged out.",
    NotificationType.Information
);
